-- PT111-S4-Q6. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT111-S4-Q6$batch12$ AND q.stimulus=$batch12$Many people are alarmed about the population explosion. They fail to appreciate that the present rise in population has in fact been followed by equally potent economic growth. Because of this connection between an increase in population and an increase in economic activity, population control measures should not be taken.$batch12$ AND q.prompt=$batch12$The questionable pattern of reasoning in the argument above is most similar to that in which one of the following?$batch12$ AND q.correct_choice=$batch12$B$batch12$) THEN RAISE EXCEPTION 'Question changed: PT111-S4-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT111-S4-Q6$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT111-S4-Q6'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT111-S4-Q6$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$No population control measures should be taken.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Population growth has been followed by equally strong economic growth.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$A concern is dismissed because the worrying thing happens alongside something good. The good result doesn't show the problem isn't real or that it caused the good.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Dismiss a concern because it goes along with success, so take no action.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT111-S4-Q6$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$This says subscribers should pay their share. No good result is used to dismiss a concern.$batch12$), ($batch12$B$batch12$, $batch12$Complaints about the manager are dismissed because sales are rising, so no action is taken. Same move.$batch12$), ($batch12$C$batch12$, $batch12$This suggests a compromise. It doesn't dismiss the concern.$batch12$), ($batch12$D$batch12$, $batch12$This appeals to enjoyment and variety. No good outcome tied to the problem.$batch12$), ($batch12$E$batch12$, $batch12$This predicts prices will fall, a different reasoning error.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT111-S4-Q6$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
